def find_secret_code(n, x, y, bob_guess):
    # Initialize the secret code with possible values
    secret_code = [0] * n
    # Calculate the number of correct colors x
    correct_indices = set()
    for i in range(n):
        if bob_guess[i] == bob_guess[x]:
            correct_indices.add(i)
    x = len(correct_indices)

    # Calculate the size of the multiset intersection y
    color_count = {}
    for color in bob_guess:
        color_count[color] = color_count.get(color, 0) + 1
    y = 0
    for i in range(n):
        if color_count.get(bob_guess[i], 0) > 0:
            y += 1
            color_count[bob_guess[i]] -= 1
    y = y - (n - x)

    # Check if the calculated x and y match the given x and y
    if x != x or y != y:
        return "NO"

    # Fill the secret code based on the correct indices and the remaining colors
    remaining_colors = list(range(1, n+2))
    for i in correct_indices:
        secret_code[i] = bob_guess[i]
        remaining_colors.remove(bob_guess[i])

    # Fill the remaining positions with the remaining colors
    for i in range(n):
        if secret_code[i] == 0:
            secret_code[i] = remaining_colors.pop(0)

    return "YES\n" + " ".join(map(str, secret_code))

